const withdrawMyPendingVersions = `-- name: WithdrawMyPendingVersions :exec
SELECT withdraw_pending_versions($1)
`

// Row-level security context: only versions of the caller's organizations.
func (q *Queries) WithdrawMyPendingVersions(ctx context.Context, pListing uuid.UUID) error {
	_, err := q.db.Exec(ctx, withdrawMyPendingVersions, pListing)
	return err
}

const withdrawPendingVersions = `-- name: WithdrawPendingVersions :exec
UPDATE listing_versions SET status = 'withdrawn' WHERE listing_id = $1 AND status = 'pending'
`

// System context, after the caller's access was checked.
func (q *Queries) WithdrawPendingVersions(ctx context.Context, listingID uuid.UUID) error {
	_, err := q.db.Exec(ctx, withdrawPendingVersions, listingID)
	return err
}
